import math

def compute_integral(func, a, b, n=1000):
    # Use 3/8 rule or adaptive algorithm to achieve correct integration accuracy
    h = (b - a) / n
    integral = func((2 * a + 2 * b) / 4)
    for i in range(1, n):
        x = a + i * h
        if i % 3 == 0:
            integral += 3 * func((2 * a + 2 * b) / 4 + i * h / 3)
        else:
            integral += func(x)
    return integral

def main():
    func = lambda x: math.exp(-x**2)
    a = -5
    b = 5
    integral = compute_integral(func, a, b)
    print(integral)

if __name__ == "__main__":
    main()

